cd /tmp/m; for n in def l64 stat; do p=/tmp/m/p-$n; echo "=== $n"; ls -l $p/bin/durfmt | awk '{print $9,$10,$11}'; $p/bin/isodur --version; $p/bin/durfmt --style long PT1H30M2S P3DT4H; $p/bin/isodur fmt --style long --lang de P2Y1M; ld=$(ls -d $p/lib*); export PKG_CONFIG_PATH=$ld/pkgconfig; pkg-config --cflags --libs --static isodur; pkg-config --variable=pkgdatadir isodur; pkg-config --modversion isodur; cat $ld/pkgconfig/isodur.pc | head -9; printf '#include <isodur/isodur.h>
#include <stdio.h>
int main(void){isodur_t d;isodur_parse("PT1.5S",&d);printf("%%lld %%s\n",isodur_total_ms(&d),isodur_version());return 0;}
' > /tmp/a.c; if [ $n = stat ]; then gcc /tmp/a.c -o /tmp/a $(pkg-config --cflags isodur) $(pkg-config --static --libs isodur) && /tmp/a; else gcc /tmp/a.c -o /tmp/a $(pkg-config --cflags --libs isodur) && /tmp/a; fi; unset PKG_CONFIG_PATH; done; nm -D --defined-only p-def/lib/libisodur.so.2.1.0 | grep ' T '; readelf -d p-def/lib/libisodur.so.2.1.0 | grep -E 'SONAME|NEEDED'; ls -l /tmp/m/p-def/lib | head
